from pathlib import Path
import py_compile,shutil
ROOT=Path.cwd()
PKG=ROOT/'qseries_v2/oracle_strategy_intelligence/solana_money/mriya_python_paper_arb'
for n in ('exactpool.py','hotpath.py','crosslisted.py','scanner.py','core.py'):
    p=PKG/n
    if not p.is_file(): raise SystemExit('[FAIL] missing prior arb dependency: '+str(p.relative_to(ROOT)))
BACK=ROOT/'runtime_state/qseries/qsb038h_backup';BACK.mkdir(parents=True,exist_ok=True)
for n in ('hunter.py',):
    p=PKG/n
    if p.exists(): shutil.copy2(p,BACK/n)
(PKG/'hunter.py').write_text('from __future__ import annotations\nimport argparse,json,time\nfrom pathlib import Path\nfrom . import exactpool as exact\n\nDEFAULT_INTERVAL=1.5\nDEFAULT_MAX_CYCLES=0   # 0 = run until Ctrl+C\n\ndef summarize(r):\n    b=(r or {}).get("best")\n    if not b:\n        return {"candidate":False,"reason":"NO_VALID_QUOTE"}\n    return {\n        "candidate":bool(b.get("pre_sim_candidate")),\n        "token":b.get("token"),\n        "direction":b.get("direction"),\n        "pump_pool":b.get("pump_pool"),\n        "meteora_pool":b.get("pool"),\n        "start_sol":b.get("start_sol"),\n        "end_sol":b.get("end_sol"),\n        "net_sol":b.get("net_sol"),\n        "net_bps":b.get("net_bps"),\n        "slot_spread":b.get("slot_spread"),\n        "pump_transaction_present":b.get("pump_transaction_present"),\n    }\n\ndef run_loop(root,interval=DEFAULT_INTERVAL,max_cycles=DEFAULT_MAX_CYCLES,runner=exact.run):\n    root=Path(root)\n    cycle=0\n    best_seen=None\n    hits=0\n    state=root/"runtime_state/qseries/qsb038h_continuous_profit_hunter"\n    state.mkdir(parents=True,exist_ok=True)\n    ledger=state/"candidates.jsonl"\n    while True:\n        cycle+=1\n        t0=time.time()\n        print(f"[CYCLE {cycle}] scanning live cross-listed PumpSwap/Meteora markets",flush=True)\n        try:\n            r=runner(root)\n            s=summarize(r)\n        except KeyboardInterrupt:\n            raise\n        except Exception as e:\n            print(f"[CYCLE_ERROR] {type(e).__name__}: {e}",flush=True)\n            s={"candidate":False,"reason":f"{type(e).__name__}: {e}"}\n        if "net_bps" in s and s.get("net_bps") is not None:\n            if best_seen is None or float(s["net_bps"])>float(best_seen.get("net_bps",-1e99)):\n                best_seen=dict(s)\n        if s.get("candidate"):\n            hits+=1\n            rec={"observed_unix":time.time(),"cycle":cycle,**s,"execution_authority":False,\n                 "truth":"PRE_SIM_CANDIDATE_ONLY"}\n            with ledger.open("a",encoding="utf-8") as f:\n                f.write(json.dumps(rec,sort_keys=True)+"\\n")\n            print("[PROFIT_CANDIDATE] token=%s dir=%s start=%.6f end=%.9f net=%+.9f bps=%+.2f spread=%s tx_present=%s"%(\n                s["token"],s["direction"],float(s["start_sol"]),float(s["end_sol"]),\n                float(s["net_sol"]),float(s["net_bps"]),s["slot_spread"],s["pump_transaction_present"]),flush=True)\n            print("[ACTION] candidate captured for atomic transaction composition + simulateTransaction; no live order sent",flush=True)\n        else:\n            if s.get("net_bps") is not None:\n                print("[NO_TRADE] best_net_bps=%+.2f spread=%s"%(\n                    float(s["net_bps"]),s.get("slot_spread")),flush=True)\n            else:\n                print("[NO_TRADE] %s"%s.get("reason","NO_CANDIDATE"),flush=True)\n        elapsed=time.time()-t0\n        snap={"revision":"QSB_038H","cycle":cycle,"hits":hits,"last":s,"best_seen":best_seen,\n              "elapsed_seconds":elapsed,"execution_authority":False}\n        (state/"status.json").write_text(json.dumps(snap,indent=2),encoding="utf-8")\n        if max_cycles and cycle>=max_cycles:\n            return snap\n        time.sleep(max(0.0,float(interval)-elapsed))\n\ndef main(argv=None):\n    ap=argparse.ArgumentParser()\n    ap.add_argument("--interval",type=float,default=DEFAULT_INTERVAL)\n    ap.add_argument("--max-cycles",type=int,default=DEFAULT_MAX_CYCLES)\n    a=ap.parse_args(argv)\n    print("[QSB-038H] CONTINUOUS PROFIT HUNTER",flush=True)\n    print("[MODE] scans continuously; captures only exact-pool fresh positive pre-sim candidates",flush=True)\n    print("[SAFETY] PAPER_ONLY=True execution_authority=FALSE",flush=True)\n    try:\n        run_loop(Path.cwd(),a.interval,a.max_cycles)\n    except KeyboardInterrupt:\n        print("[STOP] user interrupted scanner",flush=True)\n\nif __name__=="__main__":\n    main()\n',encoding='utf-8')
(ROOT/'test_qsb_038h_continuous_profit_hunter.py').write_text('import unittest,tempfile\nfrom pathlib import Path\nfrom qseries_v2.oracle_strategy_intelligence.solana_money.mriya_python_paper_arb import hunter\n\nclass T(unittest.TestCase):\n    def test_summary_positive_candidate(self):\n        r={"best":{"pre_sim_candidate":True,"token":"T","direction":"PUMP_TO_METEORA",\n                   "pump_pool":"P","pool":"M","start_sol":.03,"end_sol":.0302,\n                   "net_sol":.00019,"net_bps":63.3,"slot_spread":1,\n                   "pump_transaction_present":True}}\n        s=hunter.summarize(r)\n        self.assertTrue(s["candidate"]);self.assertEqual(s["pump_pool"],"P")\n        print("[PASS] qualifying 038G result becomes profit candidate")\n\n    def test_summary_negative_rejected(self):\n        r={"best":{"pre_sim_candidate":False,"token":"T","net_bps":-10,"slot_spread":1}}\n        self.assertFalse(hunter.summarize(r)["candidate"])\n        print("[PASS] losing/nonqualified route is never admitted")\n\n    def test_loop_persists_candidate(self):\n        calls={"n":0}\n        def runner(root):\n            calls["n"]+=1\n            return {"best":{"pre_sim_candidate":True,"token":"T","direction":"METEORA_TO_PUMP",\n              "pump_pool":"P","pool":"M","start_sol":.05,"end_sol":.0502,\n              "net_sol":.00019,"net_bps":38.0,"slot_spread":1,"pump_transaction_present":True}}\n        with tempfile.TemporaryDirectory() as td:\n            st=hunter.run_loop(td,interval=0,max_cycles=1,runner=runner)\n            p=Path(td)/"runtime_state/qseries/qsb038h_continuous_profit_hunter/candidates.jsonl"\n            self.assertTrue(p.is_file());self.assertEqual(st["hits"],1)\n        print("[PASS] positive candidate is captured to append-only ledger")\n\n    def test_loop_does_not_persist_no_trade(self):\n        def runner(root):\n            return {"best":{"pre_sim_candidate":False,"token":"T","net_bps":5.0,"slot_spread":1}}\n        with tempfile.TemporaryDirectory() as td:\n            st=hunter.run_loop(td,interval=0,max_cycles=1,runner=runner)\n            p=Path(td)/"runtime_state/qseries/qsb038h_continuous_profit_hunter/candidates.jsonl"\n            self.assertFalse(p.exists());self.assertEqual(st["hits"],0)\n        print("[PASS] nonqualified market state produces no candidate record")\n\n    def test_execution_authority_false(self):\n        import inspect\n        s=Path(inspect.getfile(hunter)).read_text(encoding="utf-8")\n        self.assertIn(\'"execution_authority":False\',s)\n        self.assertNotIn("sendTransaction",s)\n        print("[PASS] continuous hunter cannot send live orders")\n\nif __name__=="__main__":\n    unittest.main(verbosity=2)\n',encoding='utf-8')
(ROOT/'run_qsb_038h_continuous_profit_hunter.py').write_text("from qseries_v2.oracle_strategy_intelligence.solana_money.mriya_python_paper_arb.hunter import main\nif __name__=='__main__':main()\n",encoding='utf-8')
for p in (PKG/'hunter.py',ROOT/'test_qsb_038h_continuous_profit_hunter.py',ROOT/'run_qsb_038h_continuous_profit_hunter.py'): py_compile.compile(str(p),doraise=True)
